work/app/tests/timetables.test.ts の冒頭、`import type { EntryRef, Timetable } from "../src/api/types";` から `const ttB: Timetable = {...};`（約40行目の閉じ括弧）までを、次のコードに置き換える。それ以降の describe 内のテストはそのまま使える。

```ts
import { describe, it, expect } from "vitest";
import type { Timetable } from "../src/api/types";
import {
  emptyRegistry,
  findTimetable,
  putTimetable,
  removeTimetable,
  allCurrent,
} from "../src/core/timetables";

const ttA: Timetable = { days: [1, 2, 3, 4, 5], periods: [{ id: "p1", label: "1限", start: "09:00", end: "10:30" }], slots: [{ day: 2, periodId: "p1", title: "A校の授業", folders: [] }], place: null };
const ttB: Timetable = { days: [1, 2, 3, 4, 5], periods: [{ id: "q1", label: "1時間目", start: "09:30", end: "10:20" }], slots: [{ day: 2, periodId: "q1", title: "B校の授業", folders: [] }], place: null };
const a = { id: "1:a", path: "C:\\学業\\A校" };
const b = { id: "1:b", path: "C:\\学業\\B校" };
```

`EntryRef` の import は不要になる（`const a: EntryRef` の型注釈も外す）。describe 内で `const moved: EntryRef = {...}` と `const missing: EntryRef = {...}` と書いてある2か所は、`: EntryRef` を削除して `const moved = { id: "1:a", path: "D:\\moved\\A校" };` と `const missing = { id: "1:c", path: "D:\\C校" };` にする。他のテスト本体（9:45 で2件、9:15 で1件、10:25 で1件、10:45 で[]、水曜で[]、put/remove/find）は変更不要。
